import hashlib
import math


class BloomFilter:
    """
    A BloomFilter implementation that uses a bit array and multiple hash functions to manage the presence of items while allowing for false positives.
    The size of the bit array and the number of hash functions are calculated based on the expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the size of the bit array (m)
        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)
        # Calculate the number of hash functions (k)
        self.hash_count = self._optimal_number_of_hash_functions(self.size, expected_items)

        # Initialize the bit array
        self.bit_array = [0] * self.size

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-(n * math.log(p)) / (math.log(2) ** 2))

    def _optimal_number_of_hash_functions(self, m: int, n: int) -> int:
        """Calculate the optimum number of hash functions."""
        return max(1, round(m / n * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Create k hash values for a given item."""
        return [(hashlib.md5(item.encode()).hexdigest() + str(i)) for i in range(self.hash_count)]

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for h in self._hashes(item):
            index = int(h, 16) % self.size
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        for h in self._hashes(item):
            index = int(h, 16) % self.size
            if self.bit_array[index] == 0:
                return False
        return True

