class BloomFilter:
    """
    A simple implementation of a Bloom Filter.
    This design uses a bit array to test membership of items with a given false positive rate.
    Optimal size of the bit array and number of hash functions are calculated based on expected items count and desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal size of the bit array
        self.size = self._optimal_size()
        # Calculate optimal number of hash functions
        self.num_hashes = self._optimal_num_hashes()

        # Create the bit array using a simple list of booleans
        self.bit_array = [False] * self.size

    def _optimal_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return int(-self.expected_items * math.log(self.false_positive_rate) / (math.log(2) ** 2))

    def _optimal_num_hashes(self) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((self.size / self.expected_items) * math.log(2)))

    def _hashes(self, item: str) -> set:
        """Generate hash indices for a given item using multiple hash functions."""
        hashes = set()
        for i in range(self.num_hashes):
            hash_value = hashlib.md5((item + str(i)).encode()).hexdigest()
            index = int(hash_value, 16) % self.size
            hashes.add(index)
        return hashes

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for index in self._hashes(item):
            self.bit_array[index] = True

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        for index in self._hashes(item):
            if not self.bit_array[index]:
                return False
        return True

import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array and multiple hash functions 
    to efficiently check membership of items. The size of the bit array and the number of 
    hash functions are computed based on the expected number of items and the desired 
    false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        if expected_items <= 0:
            raise ValueError("Expected items must be a positive integer.")
        if false_positive_rate <= 0 or false_positive_rate >= 1:
            raise ValueError("False positive rate must be between 0 and 1.")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the optimal size of the bit array
        self.bit_array_size = self._calculate_bit_array_size()
        self.num_hashes = self._calculate_num_hashes()

        # Create a bit array initialized to 0
        self.bit_array = [0] * self.bit_array_size

    def _calculate_bit_array_size(self) -> int:
        """Calculates the size of the bit array needed."""
        return int(- (self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_num_hashes(self) -> int:
        """Calculates the optimal number of hash functions."""
        return max(1, int((self.bit_array_size / self.expected_items) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generates multiple hash values for the item."""
        return [int(hashlib.md5((item + str(i)).encode()).hexdigest(), 16) % self.bit_array_size for i in range(self.num_hashes)]

    def add(self, item: str) -> None:
        """Adds an item to the Bloom Filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Checks if an item is in the Bloom Filter."""
        return all(self.bit_array[hash_value] for hash_value in self._hashes(item))
